INSERT INTO cities (name, description) VALUES
('Ижевск, Удмуртия', 'Столица Удмуртской Республики, известная своими оружейными заводами и культурой удмуртов. Город сочетает промышленное наследие с современными достопримечательностями: музеями, зоопарком и благоустроенной набережной Ижевского пруда.'),

('Казань, Татарстан', 'Столица Татарстана и „Третья столица России“ с тысячелетней историей. Главные достопримечательности: Казанский Кремль (объект ЮНЕСКО), мечеть Кул‑Шариф, Благовещенский собор, Дворец земледельцев и пешеходная улица Баумана.'),

('Челябинск, Челябинская область', 'Крупный промышленный центр и „город металлургов“ на Южном Урале, расположенный на границе Европы и Азии. Окружён живописными природными ландшафтами: озёрами, горами и лесами. Туристов привлекают исторические музеи, прогулочная зона — Кировка (челябинский Арбат), а также возможность активного отдыха и экскурсий в близлежащие природные парки.'),

('Москва, Московская область', 'Столица России и её крупнейший город, политический и экономический центр страны. Богатое историческое наследие представлено Московским Кремлём, Красной площадью, Храмом Христа Спасителя и множеством музеев (в т. ч. Третьяковской галереей). Современная Москва предлагает обширную сеть парков, театров, концертных площадок и развлекательных комплексов.'),

('Санкт‑Петербург, Ленинградская область', 'Культурная столица России, основанная Петром I в начале XVIII века. Известна дворцами, музеями, каналами и разводными мостами. Исторический центр — объект ЮНЕСКО. Особенно популярен у туристов летом в период белых ночей. Ключевые достопримечательности: Дворцовая площадь, Петропавловская крепость, Исаакиевский собор.'),

('Владивосток, Приморский край', 'Крупнейший порт на Дальнем Востоке и „ворота России в Азию“, расположенный на сопках у берегов Японского моря. Знаменит панорамными видами на залив Золотой Рог, мостом на остров Русский, Корабельной набережной и подводной лодкой‑музеем С‑56. Город сочетает морскую историю с современной инфраструктурой.'),

('Сочи, Краснодарский край', 'Главный курорт России на побережье Чёрного моря. Известен Олимпийским парком, дендрарием и горными курортами Красной Поляны. Развитая туристическая инфраструктура делает город популярным круглогодично.'),

('Екатеринбург, Свердловская область', 'Столица Урала и крупный мегаполис с богатой промышленной и культурной историей. Знаковые места: Храм‑на‑Крови, Ельцин‑Центр, набережная реки Исети (Плотинка), современные арт‑объекты и небоскрёбы делового центра. Город славится музеями, театрами и активной культурной жизнью.'),

('Новосибирск, Новосибирская область', 'Крупнейший город Сибири и важный научный, культурный и транспортный центр. Известен Академгородком, Новосибирским театром оперы и балета (НОВАТ — одним из крупнейших в России), зоопарком (одним из самых больших в стране) и множеством музеев.'),

('Калининград, Калининградская область', 'Самый западный город России, бывшая столица Восточной Пруссии — Кёнигсберг. Сочетает европейскую архитектуру с российской историей. Главные достопримечательности: Кафедральный собор на острове Канта, Рыбная деревня и форты города.'),

('Мурманск, Мурманская область', 'Крупнейший город за Полярным кругом и важнейший порт России в Арктике.'), 

('Петропавловск-Камчатский, Камчатский край', 'Административный центр Камчатского края, расположенный на берегу Авачинской бухты Тихого океана. Город окружён действующими вулканами (Авачинская и Корякская сопки), рядом находится знаменитый Халактырский пляж с чёрным вулканическим песком. Основан в 1740 году, носит звание „Город воинской славы“. Важный морской порт и отправная точка для путешествий по Камчатке.');